from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.sw_rollback.classical_sw_rollback.sw_rollback_prototype import SwRollback


class SwRollbackFactory(OperationFactoryPrototype):
    def __init__(self):
        super(SwRollbackFactory, self).__init__()

    def get_kpi(self, operability=False):
        """
        Gets kpi for software rollback operation.
        :return: dictionary with timeout, requirement and operation description for software rollback
        :rtype: dict
        """
        return SwRollback(self.bts).get_kpi(operability=operability)
